import { Component, effect, inject, NgZone, OnInit, signal } from '@angular/core';
import { FormBuilder, FormControl, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';
import { ActivatedRoute, Router, RouterModule } from '@angular/router';
import { AuthenticationService } from '../../userservices/authentication.service';
import { AlertService } from '../../../utils/alert/alert.service';
import { first } from 'rxjs';
import { AlertComponent } from '../../../utils/alert/alert/alert.component';

@Component({
  selector: 'user-profile',
  imports: [ReactiveFormsModule, AlertComponent, RouterModule],
  templateUrl: './user-profile.html',
  styleUrl: './user-profile.css',
})
export class UserProfile implements OnInit {

  private formBuilder = inject(FormBuilder);
  private route = inject(ActivatedRoute);
  private router = inject(Router);
  private authenticationService = inject(AuthenticationService);
  private alertService = inject(AlertService);
  private zone = inject(NgZone);

  readOnly = signal<boolean>(true);
  loading = signal<boolean>(false);
  submitted = signal<boolean>(false);

  profileForm: FormGroup;

  returnUrl: string | null = null;

  constructor() {
    this.profileForm = this.formBuilder.group({
      firstname: ['', Validators.required],
      lastname: ['', Validators.required],
      address: ['', Validators.required],
      country: ['', Validators.required]
    });

    effect(() => {
      const disableAll = this.readOnly();
      if (disableAll) {
        // { emitEvent: false } prevents unnecessary statusChange loops
        this.profileForm.disable({ emitEvent: false });
      } else {
        this.profileForm.enable({ emitEvent: false });
      }
    });
  }

  ngOnInit() {
    this.returnUrl = this.route.snapshot.queryParams['returnUrl'] || '/user/dashboard';
    this.authenticationService.getUserProfileData().subscribe((d) => {
      this.profileForm.patchValue({
        firstname: d.firstname,
        lastname: d.lastname,
        address: d.useraddress,
        country: d.usercountery

      })
    })

  }

  editClickHandling() {
    this.readOnly.update(() => !this.readOnly())
  }

  get f() { return this.profileForm?.controls; };

  onSubmit() {
    this.submitted.set(true);

    // stop here if form is invalid
    if (this.profileForm?.invalid) {
      return;
    }
    this.loading.set(true);

    this.authenticationService.updateUser(this.f?.['firstname'].value, this.f?.['lastname'].value, this.f?.['address'].value, this.f?.['country'].value)
      .pipe(first())
      .subscribe({
        next: (data) => {
          if (data['success']) {
            this.alertService.success(data['ops']);
            this.zone.run(() => {
              this.router.navigate([this.returnUrl]);
            })
          } else {
            this.alertService.error(data['ops']);
            this.loading.set(false);
          }
        },
        error: (error) => {
          this.alertService.error(error);
          this.loading.set(false);
        },
        complete: () => { this.loading.set(false) }
      })
  }

}
